SELECT     rr.SOURCE_TYPE,     rr.STATUS,     rr.ITEM,     rr.MASTER_ITEM,     rr.ITEM_TYPE,     im.ITEM_DESC,     rr.DEPT,     rr.CLASS,     rr.SUBCLASS,     rr.BUYER,     rr.LOCATION,     rr.LOC_TYPE,     rr.PHYSICAL_WH,     rr.STOCK_CAT,     rr.REPL_METHOD,     rr.REPL_ORDER_CTRL,     rr.PRIMARY_REPL_SUPPLIER,     s.SUP_NAME AS SUPPLIER_NAME,     rr.ORIGIN_COUNTRY_ID,     il.STATUS AS ITEM_LOC_STATUS,     il.UNIT_RETAIL,     isc.UNIT_COST,     isc.SUPP_PACK_SIZE,     isc.INNER_PACK_SIZE,     isc.TI,     isc.HI,     isc.MIN_ORDER_QTY,     isc.MAX_ORDER_QTY,     isc.LEAD_TIME AS SUPP_LEAD_TIME,     rr.ORIG_RAW_ROQ,     rr.RAW_ROQ,     rr.PRESCALE_ROQ,     rr.ORDER_ROQ,     rr.PACK_QTY,     rr.NET_INVENTORY,     rr.STOCK_ON_HAND,     rr.ON_ORDER,     rr.IN_TRANSIT_QTY,     rr.ORDER_POINT,     rr.ORDER_UP_TO_POINT,     rr.MIN_STOCK,     rr.MAX_STOCK,     rr.SAFETY_STOCK,     rr.DUE_IND,     rr.ESTIMATED_STOCK_OUT,     rr.ACCEPTED_STOCK_OUT,     rr.REVIEW_CYCLE,     rr.ACTIVATE_DATE,     rr.DEACTIVATE_DATE,     rr.NEED_DATE,     rr.REPL_DATE,     CASE         WHEN rr.ORDER_ROQ <= 0 THEN 'Zero/Negative ROQ'         WHEN rr.NET_INVENTORY > rr.ORDER_UP_TO_POINT THEN 'Over Max Stock'         WHEN rr.NET_INVENTORY < rr.ORDER_POINT THEN 'Below Order Point'         WHEN rr.DUE_IND = 'Y' THEN 'Stock Out Risk'         ELSE 'OK'     END AS VALIDATION_FLAG FROM rds_wv_repl_results rr INNER JOIN rds_wv_item_master im ON im.ITEM = rr.ITEM INNER JOIN rds_wv_item_loc il ON il.ITEM = rr.ITEM AND il.LOC = rr.LOCATION LEFT JOIN rds_wv_item_supp_country isc ON isc.ITEM = rr.ITEM AND isc.SUPPLIER = rr.PRIMARY_REPL_SUPPLIER AND isc.ORIGIN_COUNTRY_ID = rr.ORIGIN_COUNTRY_ID LEFT JOIN rds_wv_sups s ON s.SUPPLIER = rr.PRIMARY_REPL_SUPPLIER WHERE rr.STATUS IN ('W', 'P')